aio_context_t aio_ctx = 0;
unsigned int nr_events = 256;
int ret;

// Creates an asynchronous I/O context
// aio_ctx must be 0 prior to call
ret = io_setup(nr_events, &aio_ctx);

// On success, aio_ctx holds the context handle
// Use io_destroy(aio_ctx) for cleanup
// ret < 0 indicates error (e.g., -EAGAIN)
// io_setup is often wrapped in a syscall() helper
// #define SYS_io_setup 245
// ret = syscall(SYS_io_setup, nr_events, &aio_ctx);
